#!/usr/bin/env node
/**
 * Integration Test Path Fixer - Corrects relative paths in integration tests
 * Converts '../utils/logger' to '../../../../utils/logger' etc.
 * 
 * Usage: node scripts/fix-integration-paths.js
 */

const fs = require('fs');
const path = require('path');

const INTEGRATION_TEST_DIR = path.join(__dirname, '../tests/integration');

/**
 * Fix relative paths in test files
 */
function fixPathsInFile(filePath) {
  let content = fs.readFileSync(filePath, 'utf8');
  let fixed = false;

  // Map of wrong paths to correct paths (for tests/integration/)
  const pathMappings = {
    // From tests/integration/ to project root
    "'../utils/": "'../../../../utils/",
    '"../utils/': '"../../../../utils/',
    "'../services/": "'../../../../services/",
    '"../services/': '"../../../../services/',
    "'../whatsapp/": "'../../../../whatsapp/",
    '"../whatsapp/': '"../../../../whatsapp/',
    "'../config/": "'../../../../config/",
    '"../config/': '"../../../../config/',
    "'../routes/": "'../../../../routes/",
    '"../routes/': '"../../../../routes/',
    "'../__mocks__/": "'../../../../__mocks__/",
    '"../__mocks__/': '"../../../../__mocks__/',
  };

  // Apply each mapping
  for (const [wrongPath, correctPath] of Object.entries(pathMappings)) {
    if (content.includes(wrongPath)) {
      content = content.replaceAll(wrongPath, correctPath);
      fixed = true;
    }
  }

  // Write only if changes made
  if (fixed) {
    fs.writeFileSync(filePath, content, 'utf8');
    return true;
  }
  return false;
}

/**
 * Main execution
 */
function main() {
  if (!fs.existsSync(INTEGRATION_TEST_DIR)) {
    console.log('❌ Integration test directory not found');
    return;
  }

  console.log('🔧 Integration Test Path Fixer\n');
  console.log('📝 Correcting relative paths in integration tests...\n');

  const files = fs.readdirSync(INTEGRATION_TEST_DIR)
    .filter(f => f.endsWith('.spec.js'))
    .map(f => path.join(INTEGRATION_TEST_DIR, f));

  let fixedCount = 0;

  files.forEach(file => {
    if (fixPathsInFile(file)) {
      console.log(`✅ ${path.basename(file)}`);
      fixedCount++;
    }
  });

  console.log(`\n✅ Fixed paths in ${fixedCount} integration test files`);
  console.log(`\n📊 Next: npm test to validate fixes`);
}

if (require.main === module) {
  main();
}

module.exports = { fixPathsInFile };
